class ZipFile::Writer
  attr_reader :byte_size

  def initialize(io = nil, digest: Digest::MD5.new, checksum_prefix: nil)
    @entries = []
    @byte_size = 0
    @output_io = io
    @output_io&.binmode
    @streamer = nil
    @digest = digest
    @checksum_prefix = checksum_prefix
  end

  def stream_to(io)
    @output_io = io
    @output_io.binmode if @output_io.respond_to?(:binmode)
  end

  def write(data)
    @output_io.write(data)
    @byte_size += data.bytesize
    @digest.update(data)
    data.bytesize
  end

  def add_file(path, content = nil, compress: true)
    @entries << path
    write_method = compress ? :write_deflated_file : :write_stored_file

    if block_given?
      streamer.public_send(write_method, path) { |sink| yield sink }
    else
      streamer.public_send(write_method, path) { |sink| sink.write(content) }
    end
  end

  def glob(pattern)
    @entries.select { |entry| File.fnmatch(pattern, entry) }.sort
  end

  def exists?(path)
    @entries.include?(path)
  end

  def close
    streamer.close
    @output_io.flush if @output_io.respond_to?(:flush)
  end

  def checksum
    [ @checksum_prefix, Base64.strict_encode64(@digest.digest) ].compact.join(":")
  end

  private
    def streamer
      @streamer ||= ZipKit::Streamer.new(self)
    end
end
RUBY
